#[derive(Default)]
pub struct MyVec<T> {
    slots: Vec<Option<T>>,
}

impl<T> MyVec<T> {
    pub fn new() -> Self {
        Self { slots: Vec::new() }
    }

    pub fn push(&mut self, value: T) {
        self.slots.push(Some(value));
    }

    /// Invariant: returns None when index out of bounds or slot emptied.
    pub fn get(&self, index: usize) -> Option<&T> {
        self.slots.get(index)?.as_ref()
    }

    pub fn remove(&mut self, index: usize) -> Option<T> {
        self.slots.get_mut(index)?.take()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn remove_takes_value_once() {
        let mut v = MyVec::new();
        v.push(7);
        assert_eq!(v.remove(0), Some(7));
        assert_eq!(v.remove(0), None);
    }
}
